:root {
  --pdf-bg: #0f172a;
  --pdf-panel-bg: #1e293b;
  --pdf-toolbar-bg: rgba(30, 41, 59, 0.95);
  --pdf-card-bg: #1e293b;
  --pdf-card-border: #334155;
  --pdf-text: #f8fafc;
  --pdf-text-muted: #94a3b8;
  --pdf-primary: #3b82f6;
  --pdf-primary-hover: #60a5fa;
  --pdf-accent: #8b5cf6;
  --pdf-success: #10b981;
  --pdf-warning: #f59e0b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body, html {
  height: 100%;
  width: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Vazirmatn', Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--pdf-bg);
  color: var(--pdf-text);
  font-size: 14px;
}

.pdf-app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

/* Header & Toolbar */
.pdf-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  background: var(--pdf-toolbar-bg);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--pdf-card-border);
  z-index: 50;
  flex-shrink: 0;
  gap: 12px;
  flex-wrap: wrap;
}

.pdf-toolbar-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pdf-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 15px;
  background: linear-gradient(135deg, #60a5fa, #a78bfa);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.pdf-doc-title {
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--pdf-text-muted);
  background: rgba(255, 255, 255, 0.05);
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.pdf-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: 500;
  border-radius: 6px;
  border: 1px solid var(--pdf-card-border);
  background: rgba(255, 255, 255, 0.05);
  color: var(--pdf-text);
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.pdf-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.2);
}

.pdf-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.pdf-btn-primary {
  background: linear-gradient(135deg, #3b82f6, #6366f1);
  border-color: transparent;
  color: #ffffff;
}

.pdf-btn-primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #2563eb, #4f46e5);
}

.pdf-btn-accent {
  background: linear-gradient(135deg, #8b5cf6, #d946ef);
  border-color: transparent;
  color: #ffffff;
}

.pdf-btn-accent:hover:not(:disabled) {
  background: linear-gradient(135deg, #7c3aed, #c026d3);
}

.pdf-btn-icon {
  padding: 6px;
  border-radius: 6px;
}

.pdf-select {
  background: var(--pdf-panel-bg);
  color: var(--pdf-text);
  border: 1px solid var(--pdf-card-border);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 13px;
  outline: none;
  cursor: pointer;
}

.pdf-page-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--pdf-text-muted);
}

.pdf-page-input {
  width: 44px;
  background: var(--pdf-panel-bg);
  border: 1px solid var(--pdf-card-border);
  border-radius: 4px;
  color: var(--pdf-text);
  text-align: center;
  padding: 4px;
  font-size: 13px;
}

/* Progress bar */
.pdf-progress-strip {
  width: 100%;
  height: 3px;
  background: rgba(255, 255, 255, 0.1);
  position: relative;
  overflow: hidden;
}

.pdf-progress-bar {
  height: 100%;
  background: linear-gradient(90deg, #3b82f6, #a855f7);
  transition: width 0.3s ease;
}

/* Main workspace */
.pdf-main-area {
  display: flex;
  flex: 1;
  overflow: hidden;
  position: relative;
}

/* Empty state / dropzone */
.pdf-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  padding: 40px;
  text-align: center;
}

.pdf-dropzone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 2px dashed rgba(255, 255, 255, 0.2);
  border-radius: 16px;
  padding: 60px 40px;
  max-width: 540px;
  width: 100%;
  background: rgba(30, 41, 59, 0.5);
  cursor: pointer;
  transition: all 0.2s ease;
}

.pdf-dropzone:hover, .pdf-dropzone.drag-active {
  border-color: var(--pdf-primary);
  background: rgba(59, 130, 246, 0.08);
  transform: translateY(-2px);
}

.pdf-dropzone-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(59, 130, 246, 0.15);
  color: var(--pdf-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.pdf-dropzone-title {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: 8px;
}

.pdf-dropzone-subtitle {
  font-size: 13px;
  color: var(--pdf-text-muted);
  line-height: 1.5;
  margin-bottom: 20px;
}

/* Split Viewer View */
.pdf-viewer-split {
  display: flex;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.pdf-canvas-column {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: auto;
  padding: 24px;
  background: #090d16;
  border-inline-end: 1px solid var(--pdf-card-border);
}

.pdf-canvas-wrapper {
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
  border-radius: 4px;
  background: #ffffff;
  position: relative;
  transition: transform 0.15s ease;
}

.pdf-canvas-wrapper canvas {
  display: block;
  max-width: 100%;
  height: auto;
}

/* Translation Column */
.pdf-translation-column {
  flex: 1;
  overflow-y: auto;
  padding: 24px 28px;
  background: var(--pdf-panel-bg);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pdf-translation-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--pdf-card-border);
}

.pdf-translation-title {
  font-size: 15px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #93c5fd;
}

/* Paragraph translation card */
.pdf-para-card {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--pdf-card-border);
  border-radius: 10px;
  padding: 16px;
  transition: all 0.15s ease;
  position: relative;
}

.pdf-para-card:hover {
  border-color: rgba(99, 102, 241, 0.4);
  background: rgba(15, 23, 42, 0.85);
}

.pdf-para-original {
  font-size: 13px;
  color: var(--pdf-text-muted);
  line-height: 1.5;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
}

.pdf-para-translated {
  font-size: 15px;
  color: var(--pdf-text);
  line-height: 1.8;
  font-family: 'Vazirmatn', -apple-system, sans-serif;
}

.pdf-para-translated.rtl {
  direction: rtl;
  text-align: right;
}

.pdf-para-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}

.pdf-term-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: rgba(139, 92, 246, 0.18);
  border: 1px solid rgba(139, 92, 246, 0.35);
  color: #c4b5fd;
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 12px;
  margin-inline-end: 6px;
  margin-top: 6px;
}

/* Floating selection translation popover */
.pdf-selection-popover {
  position: fixed;
  background: #1e293b;
  border: 1px solid #475569;
  border-radius: 10px;
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7);
  padding: 14px 16px;
  max-width: 380px;
  z-index: 100;
  animation: popoverFadeIn 0.15s ease-out;
}

@keyframes popoverFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.25);
}

file:src/styles/popup.css.content:
:root {
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --bg-main: #ffffff;
  --bg-card: #f8fafc;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --success: #16a34a;
  --warning: #f59e0b;
  --danger: #ef4444;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary: #3b82f6;
    --primary-hover: #60a5fa;
    --primary-light: #1e293b;
    --bg-main: #0f172a;
    --bg-card: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border: #334155;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  width: 360px;
  min-height: 480px;
  background-color: var(--bg-main);
  color: var(--text-main);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Vazirmatn', Oxygen, Ubuntu, Cantarell, sans-serif;
  font-size: 13px;
  line-height: 1.5;
  user-select: none;
  overflow-x: hidden;
}

body.rtl {
  direction: rtl;
  text-align: right;
}

.popup-container {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Header */
.popup-header {
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border);
  background: var(--bg-card);
}

.brand-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-icon {
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, #2563eb, #7c3aed);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
}

.brand-title {
  font-weight: 700;
  font-size: 14px;
  letter-spacing: -0.2px;
}

.brand-subtitle {
  font-size: 11px;
  color: var(--text-muted);
}

.header-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.header-btn:hover {
  background: rgba(100, 116, 139, 0.12);
  color: var(--text-main);
}

/* Status Banner */
.status-banner {
  margin: 12px 16px 4px;
  padding: 8px 12px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 500;
}

.status-banner.success {
  background: rgba(34, 197, 94, 0.12);
  color: var(--success);
  border: 1px solid rgba(34, 197, 94, 0.25);
}

.status-banner.warning {
  background: rgba(245, 158, 11, 0.12);
  color: var(--warning);
  border: 1px solid rgba(245, 158, 11, 0.25);
  cursor: pointer;
}

/* Actions Grid */
.actions-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 12px 16px;
}

.action-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: left;
}

body.rtl .action-card {
  align-items: flex-start;
  text-align: right;
}

.action-card:hover {
  border-color: var(--primary);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.1);
}

.action-card:active {
  transform: translateY(0);
}

.action-icon-wrap {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary-light);
  color: var(--primary);
}

.action-title {
  font-weight: 600;
  font-size: 12px;
  color: var(--text-main);
}

/* Quick Settings */
.quick-settings {
  padding: 0 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.setting-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}

.select-input {
  background: var(--bg-card);
  color: var(--text-main);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 8px;
  font-size: 11px;
  outline: none;
  cursor: pointer;
  max-width: 150px;
}

.select-input:focus {
  border-color: var(--primary);
}

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 36px;
  height: 20px;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--border);
  transition: 0.2s;
  border-radius: 20px;
}

.toggle-slider:before {
  position: absolute;
  content: "";
  height: 14px;
  width: 14px;
  left: 3px;
  bottom: 3px;
  background-color: white;
  transition: 0.2s;
  border-radius: 50%;
}

input:checked + .toggle-slider {
  background-color: var(--primary);
}

input:checked + .toggle-slider:before {
  transform: translateX(16px);
}

/* Footer */
.popup-footer {
  margin-top: auto;
  padding: 10px 16px;
  border-top: 1px solid var(--border);
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}

