.options-content {
  flex: 1;
  padding: 40px 48px;
  max-width: 900px;
}

.content-header {
  margin-bottom: 28px;
}

.content-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.3px;
  margin-bottom: 6px;
}

.content-desc {
  color: var(--text-muted);
  font-size: 13px;
}

/* Form Cards */
.settings-section-card {
