:root {
  --sp-bg: #0f172a;
  --sp-card-bg: #1e293b;
  --sp-border: #334155;
  --sp-text: #f8fafc;
  --sp-text-muted: #94a3b8;
  --sp-primary: #3b82f6;
  --sp-accent: #8b5cf6;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body, html {
  height: 100%;
  width: 100%;
  background-color: var(--sp-bg);
  color: var(--sp-text);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Vazirmatn', sans-serif;
  font-size: 13px;
  line-height: 1.5;
  overflow-x: hidden;
}

.sp-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  padding: 14px;
  gap: 12px;
}

/* Header */
.sp-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--sp-border);
}

.sp-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 14px;
  background: linear-gradient(135deg, #60a5fa, #c084fc);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Card */
.sp-card {
  background: var(--sp-card-bg);
  border: 1px solid var(--sp-border);
  border-radius: 10px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 600;
  color: var(--sp-text-muted);
}

.sp-text-original {
  font-size: 12px;
  color: var(--sp-text-muted);
  line-height: 1.5;
  max-height: 100px;
  overflow-y: auto;
  padding: 6px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 6px;
}

.sp-text-translated {
  font-size: 14px;
  color: var(--sp-text);
  line-height: 1.7;
}

.sp-text-translated.rtl {
  direction: rtl;
  text-align: right;
  font-family: 'Vazirmatn', -apple-system, sans-serif;
}

/* Textarea input */
.sp-textarea {
  width: 100%;
  height: 80px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--sp-border);
  border-radius: 8px;
  color: var(--sp-text);
  padding: 8px 10px;
  font-family: inherit;
  font-size: 13px;
  resize: vertical;
  outline: none;
  transition: border-color 0.15s ease;
}

.sp-textarea:focus {
  border-color: var(--sp-primary);
}

.sp-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 6px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sp-btn-primary {
  background: linear-gradient(135deg, #3b82f6, #6366f1);
  color: #ffffff;
}

.sp-btn-primary:hover:not(:disabled) {
  opacity: 0.9;
}

.sp-btn-secondary {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--sp-border);
  color: var(--sp-text);
}

.sp-btn-secondary:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.15);
}

/* Explanation badge */
.sp-term {
  padding: 4px 8px;
  background: rgba(139, 92, 246, 0.15);
  border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: 6px;
  font-size: 11px;
  margin-top: 4px;
}

.sp-term-title {
  font-weight: 600;
  color: #c4b5fd;
}

.sp-term-desc {
  color: var(--sp-text-muted);
}

